package com.neo.chevere.domain

import com.neo.chevere.data.agent.AgentState

/**
 * Represents a single message in a chat conversation.
 *
 * @property text The content of the message.
 * @property isUser `true` if the message was sent by the user, `false` if it was generated by the AI.
 * @property inferenceTimeMs The time taken in milliseconds to generate the response (if applicable).
 * @property inputTokenCount Prompt token count, with measurement quality specified by [tokenCountKind].
 * @property outputTokenCount Generated token count, with measurement quality specified by [tokenCountKind].
 * @property imageUri Optional URI of an image associated with the message.
 * @property modelName Optional name of the AI model that generated the message.
 * @property isExplicitImage `true` when the attached image should support explicit-content masking.
 * @property isImageMasked `true` when an explicit image attachment is currently hidden behind a mask.
 * @property agentState Optional AI Agent state/steps associated with this message.
 * @property agentUiContent Optional structured UI requested by an agent tool.
 * @property documentEvidence Retrieved text or an explicit no-match outcome, independent of model claims.
 * @property agentOutcome Terminal controller outcome retained when live steps are no longer available.
 * @property tokenCountKind Distinguishes historical estimates from SDK-measured counts.
 */
data class ChatMessage(
    val text: String,
    val isUser: Boolean,
    val inferenceTimeMs: Long? = null,
    val inputTokenCount: Int? = null,
    val outputTokenCount: Int? = null,
    val imageUri: String? = null,
    val modelName: String? = null,
    val isExplicitImage: Boolean = false,
    val isImageMasked: Boolean = false,
    val agentState: AgentState? = null,
    val agentUiContent: AgentUiContent? = null,
    val documentEvidence: DocumentEvidence? = null,
    val agentOutcome: AgentOutcome? = null,
    val tokenCountKind: TokenCountKind = TokenCountKind.ESTIMATED,
)
